export const LOGIX_CACHE_OPTIONS = Symbol('LOGIX_CACHE_OPTIONS');
export const LOGIX_CACHE_STORE = Symbol('LOGIX_CACHE_STORE');

/**
 * Low-level key-value store contract implemented by both RedisCacheStore (L2 Distributed)
 * and InMemoryCacheStore (L1 Fallback / Test store).
 */
export interface CacheStore {
  /** Retrieve raw string value by fully-qualified cache key. Returns null on miss. */
  getRaw(fullKey: string): Promise<string | null>;

  /** Store raw string value with a mandatory positive TTL in seconds. */
  setRaw(fullKey: string, value: string, ttlSeconds: number): Promise<void>;

  /**
   * Atomic SET-if-Not-Exists with expiration (`SET key value EX ttl NX`).
   * Returns `true` if the key was newly created (lock acquired), or `false` if it already existed.
   */
  setIfNotExistsRaw(
    fullKey: string,
    value: string,
    ttlSeconds: number,
  ): Promise<boolean>;

  /** Delete one or more fully-qualified keys. Returns number of deleted keys. */
  delRaw(fullKeys: string[]): Promise<number>;

  /** Health check probe. Returns true when the backing store is reachable. */
  ping(): Promise<boolean>;

  /** Gracefully release network sockets or background timers. */
  close(): Promise<void>;
}

export interface LogixCacheModuleOptions {
  /**
   * Short, immutable namespace owned by the microservice (e.g. `'notif'`, `'md'`, `'order'`).
   * Every key generated by this service is prefixed with `{servicePrefix}:t:{tenantId}:{key}`
   * so services never collide or read each other's internal cache state.
   */
  servicePrefix: string;

  /**
   * Default TTL in seconds when callers omit `ttlSeconds`. Defaults to 300s (5 minutes).
   */
  defaultTtlSeconds?: number;

  /**
   * Maximum number of entries kept in the local L1 fallback store. Defaults to 2000.
   */
  maxFallbackEntries?: number;

  /**
   * Optional explicit Redis URL override. If omitted, reads `REDIS_URL` from `ConfigService`.
   */
  redisUrl?: string;

  /**
   * Connection/command timeout in milliseconds for Redis operations. Defaults to 1500ms.
   */
  commandTimeoutMs?: number;
}

